import java.util.*;
class M implements Comparable<M> {
  int n;
  M(int n) { this.n = n; }
  public int compareTo(M o) { return Integer.compare(o.n, n); }
  public String toString() { return "" + n; }
}
class Main {
  public static void main(String[] args) {
    List<M> xs = new ArrayList<>(List.of(new M(1), new M(3), new M(2)));
    Collections.sort(xs);
    System.out.println(xs);
  }
}

